-- Generated from '2026 POSM Budgeting.xlsx' (tabs CURRENT STOCK and CUSTOMER LIST).
-- Safe to re-run: items match on SKU, outlets on account number.
begin;

on conflict (sku) do update set brand = excluded.brand, name = excluded.name, category = excluded.category,
  value = excluded.value, stock = excluded.stock, updated_at = now();

on conflict (account_number) do update set name = excluded.name, parent_number = excluded.parent_number,
  parent_name = excluded.parent_name, kam_name = excluded.kam_name, market = excluded.market, active = true, updated_at = now();

commit;
-- 104 items, 1638 outlets
